<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}
final class Topups {
 static function available(string $alias='p'):string{return "NOT EXISTS(SELECT 1 FROM decisions topup_hold WHERE topup_hold.payment_id=$alias.id AND topup_hold.action IN ('netopia_topup','netopia_return_review','netopia_return_partial_review','netopia_allocated') AND topup_hold.active=1)";}
 static function links():string{return "(SELECT payment_id,invoice_id,resolution,decision_id FROM payment_resolutions UNION ALL SELECT d.payment_id,d.invoice_id,CASE WHEN i.balance_cents<=0 THEN 'historical' ELSE 'associated' END,d.id FROM decisions d JOIN invoices i ON i.id=d.invoice_id WHERE d.action='netopia_topup' AND d.active=1 UNION ALL SELECT payment_id,NULL,'return_review',id FROM decisions WHERE action='netopia_return_review' AND active=1 UNION ALL SELECT payment_id,NULL,'allocated',id FROM decisions WHERE action='netopia_allocated' AND active=1)";}
 static function sumSQL(string $invoice):string{return "COALESCE((SELECT SUM(tp.gross_amount_cents) FROM decisions td JOIN netopia_payments tp ON tp.id=td.payment_id WHERE td.invoice_id=$invoice AND td.action='netopia_topup' AND td.active=1 AND tp.transfer_date IS NOT NULL),0)";}
 static function rows(\PDO $db,int $invoice):array{return query($db,"SELECT p.* FROM decisions d JOIN netopia_payments p ON p.id=d.payment_id WHERE d.invoice_id=? AND d.action='netopia_topup' AND d.active=1 ORDER BY p.transfer_date,p.id",[$invoice])->fetchAll();}
 static function apply(\PDO $db,array $actor,string $payment,string $invoice):array{permit($actor,'operate');return transaction($db,function()use($db,$actor,$payment,$invoice){$i=one($db,'SELECT * FROM invoices WHERE invoice_number=? FOR UPDATE',[$invoice]);$p=one($db,'SELECT * FROM netopia_payments WHERE canonical_external_id=? FOR UPDATE',[$payment]);if(!$i||!$p||$i['scope']==='internal')throw new Problem('Document lipsă.');$old=one($db,"SELECT * FROM decisions WHERE payment_id=? AND action='netopia_topup' AND active=1",[$p['id']]);if($old){if((int)$old['invoice_id']!==(int)$i['id'])throw new Problem('Plata suplimentară este deja rezervată.');return ['saved'=>true,'repeated'=>true];}if(one($db,'SELECT * FROM payment_resolutions WHERE payment_id=?',[$p['id']]))throw new Problem('Plata este deja asociată sau închisă.');$main=one($db,'SELECT p.* FROM payment_resolutions r JOIN netopia_payments p ON p.id=r.payment_id WHERE r.invoice_id=?',[$i['id']]);if(!$main)throw new Problem('Lipsește plata principală.');$extras=self::rows($db,(int)$i['id']);$sum=(int)$main['gross_amount_cents']+(int)$p['gross_amount_cents']+array_sum(array_column($extras,'gross_amount_cents'));if($sum!==(int)$i['amount_cents'])throw new Problem('Totalul plăților nu acoperă exact factura.');$id=decision($db,'netopia_topup',['invoice'=>$i['id'],'payment'=>$p['id']],['invoice_hash'=>$i['source_hash'],'payment_hash'=>$p['source_hash'],'main_payment'=>$main['id'],'main_amount_cents'=>(int)$main['gross_amount_cents'],'supplement_cents'=>(int)$p['gross_amount_cents'],'total_cents'=>$sum],'Plată suplimentară confirmată explicit de utilizator; împreună cu plata principală acoperă exact factura.',$actor,'topup:'.bin2hex(random_bytes(16)));audit($db,'netopia_supplement_assigned',['invoice'=>$invoice,'payment'=>$payment,'total_cents'=>$sum],$actor,$id);return ['saved'=>true,'total_cents'=>$sum];});}
 static function enrich(\PDO $db,array &$r):void{$extras=self::rows($db,(int)$r['id']);if(!$extras)return;$r['supplemental_payments']=$extras;foreach($extras as $p){$r['gross_amount_cents']+=(int)$p['gross_amount_cents'];$r['commission_cents']+=Reports::fee($p);if($p['transfer_date']){$r['transfer_amount_cents']=($r['transfer_amount_cents']??0)+(int)$p['gross_amount_cents'];$r['transfer_date']=max($r['transfer_date']??'',$p['transfer_date']);}$r['operation_number']=implode(' / ',array_filter([$r['operation_number'],$p['operation_number']]));}$r['source_review']=(bool)$r['pending_changes']||$r['scope_reason']==='retained'||(int)$r['gross_amount_cents']!==(int)$r['amount_cents'];}
}
